SELECT has_ad, COUNT(*) AS cnt
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at >= #{from}
  AND bid_at < #{to}
GROUP BY has_ad

EXPLAIN
SELECT has_ad, COUNT(*) AS cnt
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at >= #{from}
  AND bid_at < #{to}
GROUP BY has_ad

SELECT SUM(ad_cnt) AS ad_cnt,
       SUM(cnt - ad_cnt) AS empty_cnt,
       SUM(cnt) AS total_cnt
FROM bid_stat_hourly
WHERE slot_code = #{slot}
  AND stat_hour >= #{from}
  AND stat_hour < #{to}

EXPLAIN
SELECT SUM(ad_cnt) AS ad_cnt,
       SUM(cnt - ad_cnt) AS empty_cnt,
       SUM(cnt) AS total_cnt
FROM bid_stat_hourly
WHERE slot_code = #{slot}
  AND stat_hour >= #{from}
  AND stat_hour < #{to}
